const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"})[c]);
const find=(path="/AllProducts/")=>`https://findspreadsheet.com${path}`;
let lang=new URLSearchParams(location.search).get("lang")||localStorage.getItem("pikoLang")||"en";if(!locales[lang])lang="en";
let t=locales[lang],page=routes[location.pathname]||"home";
function link(p){return `${p}?lang=${lang}`}
function nav(){return `<header class="top"><div class="shell topbar"><a class="brand" href="${link("/")}" aria-label="PikoBuy Sheet home"><img src="/pikobuy.png" alt="PikoBuy" /></a><nav class="nav">${[["/",0],["/categories/",1],["/products/",2],["/articles/",3],["/faq/",4]].map(([p,i])=>`<a class="${routes[p]===page?"active":""}" href="${link(p)}">${t.nav[i]}</a>`).join("")}</nav><select class="lang" aria-label="Language">${Object.entries(locales).map(([k,v])=>`<option value="${k}" ${k===lang?"selected":""}>${v.name}</option>`).join("")}</select></div></header>`}
function cats(){return cat.map(([name,sub,path,icon],i)=>{const label=(categoryNames[lang]||categoryNames.en)[i]||[name,sub];return `<a class="cat" href="${find(path)}"><span class="cat-icon">${icon}</span><strong>${esc(label[0])}</strong><span>${esc(label[1])}</span></a>`}).join("")}
function home(){return `<section class="hero"><div class="shell hero-grid"><div><div class="eyebrow">${t.eyebrow}</div><h1>${t.hero}</h1><p>${t.intro}</p><form class="searchbox" id="search"><input aria-label="Search" required placeholder="${t.search}"><button>${t.searchBtn}</button></form><div class="hero-note">${t.note}</div></div><aside class="method-card"><h2>${t.method}</h2><ol class="steps">${t.steps.map((x,i)=>`<li><i>0${i+1}</i><span>${x}</span></li>`).join("")}</ol></aside></div></section><main class="main"><div class="shell"><section><div class="section-head"><div><div class="eyebrow">${t.labels.research}</div><h2>${t.browse}</h2></div><p>${t.browseText}</p></div><div class="cat-grid">${cats()}</div></section><section class="two"><article class="card"><h2>${t.check}</h2><p>${t.checkIntro}</p><div class="checks">${t.checks.map(x=>`<div class="check"><b>✓</b><span>${x}</span></div>`).join("")}</div><a class="small-link" href="${link("/products/")}">${t.labels.details} →</a></article><article class="card dark"><h2>${t.facts}</h2><p>${t.factsIntro}</p><a class="small-link" href="${link("/articles/")}">${t.nav[3]} →</a></article></section><section class="research">${[0,1,2].map(i=>`<div><h3>${t.fact[i*2]}</h3><p>${t.fact[i*2+1]}</p></div>`).join("")}</section></div></main>`}
function routePage(kind){let [title,intro]=t.page[kind];let inner="";if(kind==="categories")inner=`<div class="cat-grid">${cats()}</div>`;if(kind==="products")inner=`<div class="detail-list">${t.checks.map((x,i)=>`<article class="detail"><div><h3>${x}</h3><p>${t.qa[i%t.qa.length][1]}</p></div><a class="button" href="${find("/AllProducts/")}">${t.go}</a></article>`).join("")}</div>`;if(kind==="articles")inner=`<div class="research">${[0,3,6].map(i=>`<div><h3>${t.cards[i]}</h3><p>${t.cards[i+1]}</p><a class="small-link" href="${link("/articles/")}">${t.labels.research} →</a></div>`).join("")}</div>`;if(kind==="guides")inner=`<div class="two"><article class="card dark"><h2>${t.method}</h2><ol class="steps">${t.steps.map((x,i)=>`<li><i>0${i+1}</i><span>${x}</span></li>`).join("")}</ol></article><article class="card"><h2>${t.labels.summary}</h2><div class="checks">${t.checks.map(x=>`<div class="check"><b>✓</b><span>${x}</span></div>`).join("")}</div><a class="button" href="${find("/AllProducts/")}">${t.go}</a></article></div>`;if(kind==="faq")inner=`<div class="faq">${t.qa.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div>`;return `<section class="route-hero"><div class="shell"><div class="eyebrow">${t.eyebrow}</div><h1>${title}</h1><p>${intro}</p></div></section><main class="route-main"><div class="shell">${inner}</div></main>`}
function footer(){return `<footer class="footer"><div class="shell footer-grid"><div><strong>PikoSheet</strong><p>${t.note}</p></div><p>© 2026 · <a href="${find("/")}">FindSpreadsheet</a></p></div></footer><div class="toast" role="status"></div>`}
function render(){t=locales[lang];document.documentElement.lang=lang;document.title=`PikoBuy Sheet — ${t.eyebrow}`;const content=page==="home"?home():routePage(page);document.querySelector("#app").innerHTML=nav()+content+footer();document.querySelector(".lang").addEventListener("change",e=>{lang=e.target.value;localStorage.setItem("pikoLang",lang);const u=new URL(location.href);u.searchParams.set("lang",lang);history.replaceState({},"",u);render()});document.querySelector("#search")?.addEventListener("submit",e=>{e.preventDefault();const q=e.currentTarget.querySelector("input").value.trim();if(q)location.assign(`https://findspreadsheet.com/search.html?keywords=${encodeURIComponent(q)}&channelid=2`)})}
const evidenceArticle=`<article class="article"><p class="article-kicker">Research note · updated 2026</p><h2>How the PikoBuy ordering flow works: a practical, evidence-led guide</h2><p>Most people do not need another vague “spreadsheet” page. They need to know what happens between finding an item and receiving a parcel. PikoBuy’s public guide describes a six-stage workflow: choose an item on a source platform, search by link or keywords, select variants and make the first payment, review warehouse inspection information, choose and pay for international shipping, then wait for tracking after dispatch. That sequence is useful because it separates the questions that belong to the product from the questions that belong to the parcel.</p><h3>1. Start with the source listing, not the headline</h3><p>PikoBuy says shoppers can select items from Taobao, Tmall, 1688, Weidian, Yupoo and other platforms. Its guide says that a product link or keywords can be placed in the platform’s search box. The practical takeaway is simple: save the original listing and verify the variant before paying. Confirm colour, size, quantity and the visible product details while you still have the source reference. A spreadsheet title is a discovery shortcut; it is not proof that a particular seller still has stock, that a displayed variant is available, or that the final product will match a photo.</p><p>Before opening a result on FindSpreadsheet, write down the version you actually want. For clothing, that normally means the size option and a measurement reference. For shoes, it means the size convention and colourway. For electronics or accessories, it means the model, plug or specification. This is not a promise of suitability; it is a way to reduce an avoidable mismatch between the item you intended to buy and the order submitted.</p><h3>2. Treat the first payment as the purchase stage</h3><p>The official guide places variant selection and the first payment before the warehouse stage. It also notes that prices are subject to the actual purchase and that an out-of-stock order is refunded. That is an important boundary. It means a listing price is not a guaranteed final transaction outcome, and shoppers should avoid building a parcel budget from a single screenshot. Keep a little room for source-side changes and review the order status rather than assuming a link guarantees fulfilment.</p><p>Do not confuse this first payment with international delivery. The guide describes international shipping as a later, separate payment after the item reaches the warehouse. Keeping these two stages distinct makes cost planning more honest: first assess whether the individual item is worth ordering; later assess whether combining it into a parcel is worth sending.</p><h3>3. Warehouse inspection is a decision point, not a guarantee</h3><p>According to PikoBuy’s guide, arriving items are checked in, photographed for confirmation and checked for defects. The forwarding terms additionally say that forwarded goods are unpacked and inspected, while professional inspection is not available for special or professional products. These statements support a careful workflow, but they do not justify saying that every defect, authenticity question, material issue or sizing problem will be caught. Inspection photos are evidence to review, not a certificate.</p><p>Use the images to compare the order details with what arrived: colour, visible size tag where relevant, obvious damage, count of items and any details that matter to your use case. If ordinary photos do not answer a question, PikoBuy’s forwarding terms state that additional detailed photos may be purchased. That is a factual service option; whether it is worthwhile is your decision. The best time to notice a mismatch is while the item is still in the warehouse, not after the international parcel has been submitted.</p><h3>4. Understand the return window and its limits</h3><p>PikoBuy’s returns page describes a five-day warehouse return window for qualifying goods, counted as 120 hours from the hour after the order becomes “In Warehouse.” Eligibility depends on the seller offering the return guarantee, the item remaining in the resalable condition required by the seller and the item having been in the warehouse no more than five days. The policy also lists categories that may not be returnable, including customised goods, second-hand products, intimate apparel, food and various opened or unsealed products. Seller consent and the relevant platform rules still matter.</p><p>Cost is not something to guess. The policy says a no-fault return can involve return shipping, the seller’s original shipping fee and an RMB 5 service fee. For seller-caused issues such as a wrong item or quality issue, the policy says customers normally do not bear return costs, though the final case is handled with the seller. Read the current policy before acting; this page is a research guide and does not decide eligibility.</p><h3>5. Estimate shipping with real parcel inputs</h3><p>The public shipping estimator asks for destination country or region, product type, weight, length, width and height. PikoBuy’s guide also says routes differ in delivery time and billing methods. Those fields explain why no independent page can quote a reliable final price from a product title alone. Weight and dimensions belong to the parcel, not just the item. Packaging choices, consolidation and the route selected can change the calculation.</p><p>A sensible approach is to make a rough list of item weights and then treat the eventual warehouse figures as more useful than an early guess. Compare routes on their stated billing method and time information inside your account. Do not describe any route as guaranteed, cheapest for every parcel or immune from customs delays. PikoBuy’s forwarding terms say third-party logistics providers carry parcels and that cross-border risks can include customs policies, confiscation, damage, loss and peak-season delays.</p><h3>6. Keep tracking expectations realistic</h3><p>The official guide says tracking information will be available within three days after a parcel is shipped. It also notes that international shipping takes longer and advises waiting for tracking updates and delivery. “Within three days” is about the availability of tracking information after dispatch, not a delivery guarantee. Shipping time depends on the selected route, destination and factors outside an independent guide’s control.</p><p>If you use a forwarding order rather than a purchasing order, the forwarding terms say to obtain the warehouse address, complete the forwarding form, wait for receipt and photos, then submit the parcel and pay shipping as usual. The same terms say PikoBuy does not provide after-sales service for forwarded products; after-sales questions should be taken to the sender or seller, while PikoBuy can help ship goods back. That distinction is especially important when choosing where to purchase from.</p><h3>A short, useful checklist</h3><ul><li>Save the original listing and exact variant.</li><li>Confirm size, colour and quantity before the first payment.</li><li>Review warehouse photos against the order, without treating them as a guarantee.</li><li>Check the current return rules promptly after warehouse arrival.</li><li>Use destination, product type, weight and dimensions for shipping estimates.</li><li>Choose a route based on the current account information and your own risk tolerance.</li><li>Keep delivery and customs expectations realistic.</li></ul><p>This research site is independent and only helps you open relevant FindSpreadsheet results. It does not take payments, manage orders, quote final shipping or represent PikoBuy.</p></article>`;
const factFaq=[['What sources does PikoBuy list in its buying guide?','Its guide names Taobao, Tmall, 1688, Weidian, Yupoo and other platforms. It says shoppers can paste a product link or keywords into its search box.'],['What happens when an item reaches the warehouse?','PikoBuy says it checks items in, provides photo confirmation and performs a defect check. The forwarding terms also state that forwarded goods are unpacked and inspected. This is useful evidence, not a guarantee that every issue will be detected.'],['How is international shipping estimated?','The public estimator requires a destination, product type, weight, length, width and height. PikoBuy also says routes differ in delivery time and billing method, so an independent page cannot quote a final shipping price.'],['When can a qualifying item be returned?','The returns policy describes a five-day, 120-hour warehouse window for qualifying goods. Eligibility also depends on seller support and the item remaining in the resalable condition required by the seller.'],['Are all items returnable?','No. The policy lists exclusions including customised goods, second-hand items, intimate apparel, food and some opened or unsealed products. Seller and source-platform rules still apply.'],['When does tracking appear?','PikoBuy’s guide says tracking information is available within three days after a parcel is shipped. This is not a delivery-time guarantee.'],['Can this site guarantee delivery, customs clearance or final prices?','No. PikoBuy’s forwarding terms describe third-party logistics and cross-border risks. This independent research site does not sell, ship, take payments or make service promises.']];
const evidenceAddendum=`<h3>7. Make decisions while each option is still reversible</h3><p>The practical value of this workflow is timing. A colour, size or specification question is easiest to resolve before the first payment. A visible mismatch is easiest to address while warehouse information and any eligible return window are still available. A route choice is most useful when it is based on the parcel rather than a guess made from a listing. None of those steps removes the normal uncertainty of buying across marketplaces and borders. They simply prevent one early assumption from being carried unchanged through every later stage.</p><p>For that reason, save the order details, check the current policy in the account when the item reaches the warehouse, and avoid treating an old screenshot, a spreadsheet entry or another person’s parcel as a promise about your own order. Good research is specific about what is known, what must still be checked, and who can actually make the final decision.</p>`;
const researchFaqEN=[...factFaq,['Does warehouse inspection confirm authenticity or exact material?','No. The published information describes check-in, photos and defect checks. It does not say that inspection is an authenticity certification or a complete material verification service.'],['What can a buyer request at the warehouse?','The public guide says users can add requests such as minimal or reinforced packaging. Whether a request is possible for a particular order should be checked in the account rather than assumed.'],['What is different about a forwarding order?','The forwarding terms describe obtaining the warehouse address, submitting a forwarding form, waiting for receipt and photos, then submitting the parcel and paying shipping. They also say after-sales questions for forwarded goods should be taken to the sender or seller.'],['What can this independent site do?','It helps visitors research product context and open relevant FindSpreadsheet records. It cannot purchase, inspect, refund, ship, insure or track an order.']];
routePage=function(kind){
  if(kind!=="articles"&&kind!=="faq")return originalRoutePage(kind);
  const copy=localizedResearch[lang]||localizedResearch.en;
  const article=kind==="articles";
  const title=article?copy.title:t.page.faq[0];
  const intro=article?copy.intro:t.page.faq[1];
  const expansion=articleExpansion[lang]||[];
  const depth=articleDepth[lang]||[];
  const closing=articleClosing[lang]||[];
  const supportingNotes=[[t.method,t.steps.join(" ")],[t.check,`${t.checkIntro} ${t.checks.join(" · ")}`],[t.facts,`${t.factsIntro} ${t.fact.join(" ")}`],[t.cards[0],t.cards[1]],[t.cards[2],t.cards[3]],[t.cards[4],t.cards[5]],[t.qa[0][0],t.qa[0][1]],[t.qa[1][0],t.qa[1][1]],[t.qa[2][0],t.qa[2][1]],[t.qa[3][0],t.qa[3][1]]];
  const localeArticle=`<article class="article"><p class="article-kicker">${copy.label}</p><h2>${copy.title}</h2><p>${copy.intro}</p>${copy.s.map(([head,body],i)=>`<h3>${head}</h3><p>${body}</p><p>${expansion[i]||""}</p><p>${depth[i]||""}</p>`).join("")}${supportingNotes.map(([head,body])=>`<h3>${head}</h3><p>${body}</p>`).join("")}<h3>${t.labels.summary}</h3><ul>${copy.s.map(([head])=>`<li>${head}</li>`).join("")}</ul>${closing.map(p=>`<p>${p}</p>`).join("")}</article>`;
  const localeFaq=[...copy.faq,...(faqExpansion[lang]||[])];
  const inner=article?(lang==="en"?`${evidenceArticle}${evidenceAddendum}`:localeArticle):`<div class="faq">${(lang==="en"?researchFaqEN:localeFaq).map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div>`;
  return `<section class="route-hero"><div class="shell"><div class="eyebrow">${copy.label}</div><h1>${title}</h1><p>${intro}</p></div></section><main class="route-main"><div class="shell">${inner}</div></main>`;
};
const routePageLegacy=originalRoutePage;
render();
